/**
 * @file mstService.js
 * @desc Dịch vụ tra cứu mã số thuế doanh nghiệp qua nhiều nguồn API (VietQR, Xinvoice) để đảm bảo độ ổn định.
 */

const SOURCES = [
    {
        name: 'VietQR',
        url: (mst) => `https://api.vietqr.io/v2/business/${mst}`,
        parser: (res) => {
            if (res.code === '00' && res.data) {
                return {
                    name: res.data.name,
                    address: res.data.address,
                    representative: res.data.representative
                };
            }
            return null;
        }
    },
    {
        name: 'Xinvoice',
        url: (mst) => `https://api.xinvoice.vn/api/v1/business/info/${mst}`,
        parser: (res) => {
            if (res && res.data) {
                return {
                    name: res.data.name,
                    address: res.data.address,
                    representative: res.data.representative
                };
            }
            return null;
        }
    }
];

export const mstService = {
    /**
     * Tra cứu thông tin doanh nghiệp theo MST qua nhiều nguồn.
     * @param {string} mst - Mã số thuế cần tra cứu.
     * @returns {Promise<{name: string, address: string, representative: string}|null>}
     */
    async lookupMST(mst) {
        if (!mst || mst.length < 10) return null;

        let lastError = null;

        for (const source of SOURCES) {
            try {
                console.log(`[MST Service] Trying source: ${source.name}...`);
                const response = await fetch(source.url(mst), { 
                    method: 'GET',
                    headers: { 'Accept': 'application/json' },
                    signal: AbortSignal.timeout(5000) // Timeout 5s cho mỗi nguồn
                });

                if (!response.ok) throw new Error(`HTTP error ${response.status}`);

                const result = await response.json();
                const parsed = source.parser(result);

                if (parsed && parsed.name) {
                    console.log(`[MST Service] Success with ${source.name}`);
                    return parsed;
                }
            } catch (error) {
                console.warn(`[MST Service] ${source.name} failed:`, error.message);
                lastError = error;
                continue; // Thử nguồn tiếp theo
            }
        }

        console.error('[MST Service] All sources failed.', lastError);
        return null;
    }
};

