// --- Logic Thu Phóng (Zoom) ---
const ZOOM_LEVELS = [0.8, 1, 1.2]; // Nhỏ - Vừa - To
let currentZoomIdx = Storage.get('vnpt_zoom_idx') || 1; // Mặc định nấc 1 (100%)

const applyZoom = (idx) => {
    const zoom = ZOOM_LEVELS[idx];
    document.documentElement.style.setProperty('--vnpt-zoom', zoom);
    Storage.set('vnpt_zoom_idx', idx);
    showToast(`🔍 Thu phóng: ${Math.round(zoom * 100)}%`, "#1a73e8");
};

// Áp dụng zoom đã lưu ngay khi khởi tạo
applyZoom(currentZoomIdx);

window.addEventListener('keydown', (e) => {
    // Chỉ bắt sự kiện nếu đang mở widget hoặc tổ hợp phím Ctrl
    if (e.ctrlKey) {
        if (e.key === '=' || e.key === '+') { // Ctrl +
            e.preventDefault();
            if (currentZoomIdx < ZOOM_LEVELS.length - 1) {
                currentZoomIdx++;
                applyZoom(currentZoomIdx);
            }
        } else if (e.key === '-') { // Ctrl -
            e.preventDefault();
            if (currentZoomIdx > 0) {
                currentZoomIdx--;
                applyZoom(currentZoomIdx);
            }
        } else if (e.key === '0') { // Ctrl 0
            e.preventDefault();
            currentZoomIdx = 1;
            applyZoom(currentZoomIdx);
        }
    }
});

